(globalThis.TURBOPACK||(globalThis.TURBOPACK=[])).push(["object"==typeof document?document.currentScript:void 0,13974,(e,n,t)=>{n.exports={description:"Core JavaScript syntax, variables and data types.",questions:[{id:1,question:"What is the difference between let, const, and var?",answer:"const declarations cannot be reassigned, let can be reassigned, and both are block-scoped. var is function-scoped, hoisted with an undefined value, and behaves unpredictably inside loops.\n\ncode:\nlet count = 5;\ncount = 6;\nconst name = 'playwright';\nvar legacy = 'avoid me';\n\nreal example:\nIn Playwright tests, use const for locators like const submitButton = page.getByRole('button', { name: 'Submit' }) and let only for values you genuinely reassign."},{id:2,question:"What are the primitive data types in JavaScript?",answer:"The seven primitives are string, number, boolean, undefined, null, symbol, and bigint. Everything else, including arrays and functions, is an object.\n\ncode:\nconsole.log(typeof 'text');  // string\nconsole.log(typeof 42);      // number\n\nreal example:\nAn API response field you read in a Jest assertion is always one of these primitives, so checking typeof before comparing avoids surprise failures."},{id:3,question:"What is the difference between null and undefined?",answer:"undefined means a variable has been declared but not assigned a value. null is an intentional assignment meaning no value. undefined is its own type, while typeof null incorrectly returns object.\n\ncode:\nlet a;\nconsole.log(a);        // undefined\nconst b = null;\nconsole.log(b);        // null\n\nreal example:\nWhen an API omits a field, JSON.parse gives undefined; when it sends a literal null, you get null. Assertions such as expect(res.body.user).toBeNull() rely on telling them apart."},{id:4,question:"What does typeof null return and why is it surprising?",answer:"typeof null returns the string 'object', which is a long-standing bug from the original implementation. null is not actually an object.\n\ncode:\nconsole.log(typeof null);  // 'object'\n\nreal example:\nDo not trust typeof for null checks; use a strict comparison like value === null instead, which is what you need before reading properties of optional API fields."},{id:5,question:"What is NaN and how do you check for it?",answer:"NaN means Not a Number and is produced by failed numeric conversions such as Number('abc'). It is the only value not equal to itself, so you must use Number.isNaN() or the global isNaN() to test for it.\n\ncode:\nconsole.log(Number('12px'));  // NaN\nconsole.log(Number.isNaN(Number('12px')));  // true\n\nreal example:\nWhen parsing price text scraped from a page, guard with Number.isNaN so a conversion failure produces a clear assertion message instead of a silent bad compare."},{id:6,question:"What is hoisting in JavaScript?",answer:"Hoisting moves variable and function declarations to the top of their scope at compile time. var declarations are hoisted with value undefined, while let and const are hoisted into a temporal dead zone and throw if used before the declaration line.\n\ncode:\nconsole.log(x);  // undefined, not an error\nvar x = 5;\n\nreal example:\nIn test files, function declarations like describe and beforeEach hoist cleanly, but always define helper functions before calling them to keep results predictable."},{id:7,question:"Which values are falsy in JavaScript?",answer:"There are exactly six falsy values: false, 0, '' (empty string), null, undefined, and NaN. Everything else is truthy, including '0' and 'false' as strings.\n\ncode:\nif ('0') { console.log('truthy'); }   // runs\nif (0) { console.log('no'); }         // skipped\n\nreal example:\nA filter like rows.filter(row => row.name) silently drops rows whose name is an empty string, so check for undefined explicitly instead of relying on truthiness."},{id:8,question:"What is the result of typeof [] and typeof function(){}?",answer:"Both return 'object' and 'function' respectively. Arrays are objects under the hood, and functions are callable objects.\n\ncode:\nconsole.log(typeof []);     // 'object'\nconsole.log(typeof function(){});  // 'function'\n\nreal example:\nUse Array.isArray() instead of typeof when validating JSON payload fields in tests, because typeof would accept any object as an array."},{id:9,question:"What does the Number.isInteger() method do?",answer:"It returns true only when the argument is a number with no fractional part. Unlike a global check with parseInt, it rejects strings and Infinity.\n\ncode:\nconsole.log(Number.isInteger(42));    // true\nconsole.log(Number.isInteger(42.5));  // false\n\nreal example:\nAfter summing API prices, assert Number.isInteger(total) when the contract promises whole-number values such as item counts in a cart."},{id:10,question:"How do you convert a string to a number safely?",answer:"Use Number(value) for strict parsing, or parseInt/parseFloat for lenient parsing that tolerates trailing text. Number('12px') gives NaN while parseInt('12px') gives 12.\n\ncode:\nconst a = Number('12.5');\nconst b = parseFloat('12.5 USD');\n\nreal example:\nUI text like '3 items' must be parsed with parseInt before comparing to an integer, or the assertion fails even though the value is correct."},{id:11,question:"Why is 0.1 + 0.2 not equal to 0.3?",answer:"JavaScript numbers use binary floating point, so decimals cannot always be represented exactly. The sum computes to 0.30000000000000004 instead of 0.3.\n\ncode:\nconsole.log(0.1 + 0.2);  // 0.30000000000000004\n\nreal example:\nWhen asserting totals from a cart API, round first with parseFloat(total.toFixed(2)) or compare with a tolerance like expect(Math.abs(actual - expected)).toBeLessThan(0.001)."},{id:12,question:"What is dynamic typing in JavaScript?",answer:"A variable can change type at runtime because JavaScript infers type from the assigned value. The same variable can hold a string and then a number without any redeclaration.\n\ncode:\nlet x = 'hello';\nx = 42;\nconsole.log(x);  // 42\n\nreal example:\nAutomation config read from an environment variable arrives as a string even if it looks numeric, so convert it explicitly before using it in a numeric assertion."},{id:13,question:"What naming rules apply to JavaScript variables?",answer:"Names must start with a letter, underscore, or dollar sign, cannot contain spaces or hyphens, and cannot be reserved words. The convention is camelCase for variables and SCREAMING_SNAKE_CASE for constants.\n\ncode:\nconst firstName = 'Ana';\nconst MAX_TIMEOUT = 5000;\n\nreal example:\nPlaywright locators stored as const variables follow the same naming rules, which keeps test code readable and free of lint errors."},{id:14,question:"What does it mean that const does not freeze an object?",answer:"const prevents reassignment of the binding, but the object it points to can still be mutated. Properties can be added or changed even on a const object.\n\ncode:\nconst user = { name: 'Ana' };\nuser.name = 'Bob';\nconsole.log(user.name);  // 'Bob'\n\nreal example:\nA const test config object can be mutated by shared helper code, which is why tests must clone it with a spread before changing fields."},{id:15,question:"What is the difference between assigning a primitive and an object to another variable?",answer:"Primitives are copied by value, so the two variables are independent. Objects are assigned by reference, so both variables point to the same object and mutations are shared.\n\ncode:\nlet a = 5;\nlet b = a;\nb = 6;\nconsole.log(a);  // 5\nconst obj = { n: 1 };\nconst ref = obj;\nref.n = 2;\nconsole.log(obj.n);  // 2\n\nreal example:\nBuilding test data with const payload = basePayload then editing fields mutates the shared base for every test, causing order-dependent flaky tests."}]}},35999,(e,n,t)=>{n.exports={description:"Operators and type conversions in JavaScript.",questions:[{id:1,question:"What is the difference between == and === in JavaScript?",answer:"The loose equality == converts both sides to the same type before comparing, while strict equality === requires matching type and value. Strict equality is the safer default and what most matchers such as Jest toBe use internally.\n\ncode:\nconsole.log('10' == 10);   // true\nconsole.log('10' === 10);  // false\n\nreal example:\nPlaywright text assertions compare strings, so a number expected value must be converted to a string first, otherwise strict equality fails."},{id:2,question:"What does '1' + 2 evaluate to in JavaScript?",answer:"The plus operator prefers string concatenation when either operand is a string, so '1' + 2 produces the string '12'.\n\ncode:\nconsole.log('1' + 2);  // '12'\n\nreal example:\nBuilding a URL by joining a base string with a number can silently produce the wrong endpoint, so convert numbers explicitly with String() or template literals."},{id:3,question:"Why does '10' - 2 produce 8 while '10' + 2 produces '102'?",answer:"The minus operator always forces numeric conversion, so '10' - 2 is 8. The plus operator concatenates when a string is involved, producing '102'.\n\ncode:\nconsole.log('10' - 2);  // 8\nconsole.log('10' + 2);  // '102'\n\nreal example:\nArithmetic on values scraped from a page usually works, but concatenation sneaks in strings, so parse before doing math that involves the plus operator."},{id:4,question:"What is the result of '10' < '9' with both sides as strings?",answer:"It is true because relational comparison on strings compares character by character by Unicode code point, and '1' is less than '9'.\n\ncode:\nconsole.log('10' < '9');  // true\n\nreal example:\nSorting version strings or numeric columns as raw text produces wrong order; convert to numbers with Number() or subtract inside a comparator before sorting."},{id:5,question:"What does the unary plus operator do?",answer:"The unary plus attempts to convert its operand to a number. It is a shorthand for Number() but can look confusing in expressions.\n\ncode:\nconst n = +'3';\nconsole.log(n);           // 3\nconsole.log(+'12px');    // NaN\n\nreal example:\nAssigning + to the text of a price element converts it to a number for assertable arithmetic, as long as the text has no trailing characters."},{id:6,question:"How do short-circuit && and || behave?",answer:"The && operator returns the first falsy operand or the last value if all are truthy. The || operator returns the first truthy operand or the last value if all are falsy. Neither evaluates the remaining operands once it has decided.\n\ncode:\nconst name = user?.name || 'guest';\nconst ok = isAuth && isAdmin;\n\nreal example:\nA config fallback like const baseURL = process.env.URL || 'http://localhost:3000' gives a repeatable test default whenever the variable is unset."},{id:7,question:"What is the nullish coalescing operator ?? and how does it differ from ||?",answer:"The ?? operator falls back only when the left side is null or undefined. The || operator falls back for any falsy value including 0, empty string, and false.\n\ncode:\nconst a = 0 ?? 'fallback';     // 0\nconst b = 0 || 'fallback';     // 'fallback'\n\nreal example:\nWhen a config value of 0 is meaningful, such as a wait time in seconds, use ?? so an explicit 0 is not replaced by the default."},{id:8,question:"What does Boolean('0') return and why?",answer:"Boolean('0') returns true because '0' is a non-empty string, and all non-empty strings are truthy regardless of content.\n\ncode:\nconsole.log(Boolean('0'));  // true\nconsole.log(Boolean(0));    // false\n\nreal example:\nChecking if a form field has a value with if (inputValue) wrongly treats the string '0' as present, which is correct here, but be careful when the field legitimately holds the number 0."},{id:9,question:"What is type coercion and when does it cause bugs?",answer:"Type coercion is the automatic conversion of values when operators mix types. It causes bugs because the developer's intent rarely matches the conversion rule, for example relational operators converting strings to numbers.\n\ncode:\nconsole.log('10' - 5);   // 5\nconsole.log('10' * 2);   // 20\n\nreal example:\nAssertions comparing an API number against UI text fail when one side coerces; convert both sides to the same type first."},{id:10,question:"What does the remainder operator % do?",answer:"It returns the remainder after division, not the quotient. It is useful for checking divisibility and cycling through ranges.\n\ncode:\nconsole.log(10 % 3);   // 1\nconsole.log(6 % 2);    // 0\n\nreal example:\nLooping over test users with users[i % users.length] rotates through the array infinitely without going out of bounds."},{id:11,question:"What is the difference between ++i and i++?",answer:"Both increment i by one. ++i returns the value after incrementing, while i++ returns the value before incrementing.\n\ncode:\nlet a = 1;\nconsole.log(++a);  // 2\nlet b = 1;\nconsole.log(b++);  // 1\nconsole.log(b);    // 2\n\nreal example:\nIn retry loops the difference rarely matters, but avoiding the prefix-postfix distinction keeps test helper code obvious and review-friendly."},{id:12,question:"How do you convert a value to a string, a number, and a boolean explicitly?",answer:"Use String(value), Number(value), and Boolean(value). These constructor-style conversions make intent clear compared to relying on implicit coercion.\n\ncode:\nconst s = String(42);\nconst n = Number('42');\nconst b = Boolean(1);\n\nreal example:\nSerializing a test ID with String(id) before placing it in a dynamic selector guarantees a clean match against DOM attributes."},{id:13,question:"What is the difference between parseInt and Number for parsing strings?",answer:"Number parses the whole string and returns NaN on any invalid character, while parseInt reads leading digits and ignores trailing text. parseInt also needs a radix for old-style code.\n\ncode:\nconsole.log(parseInt('42px', 10));  // 42\nconsole.log(Number('42px'));        // NaN\n\nreal example:\nCSS-like text such as 'width: 100px' is parsed with parseInt to extract 100, while strict JSON numbers use Number."},{id:14,question:"What is the exponentiation operator and how is it different from Math.pow?",answer:"The exponentiation operator ** is shorthand for raising a base to a power, equivalent to Math.pow(base, exp). It is available in ES2016 and later.\n\ncode:\nconsole.log(2 ** 3);          // 8\nconsole.log(Math.pow(2, 3));  // 8\n\nreal example:\nCalculating two-percent growth over multiple retry rounds in a load-test calculation is more readable with ** than nested Math.pow calls."},{id:15,question:"What is the result of comparing [] == false?",answer:"It is true. The loose equality coerces both sides: the empty array converts to the string '', then to 0, and false also converts to 0.\n\ncode:\nconsole.log([] == false);  // true\nconsole.log([] === false); // false\n\nreal example:\nThis is a classic trap that causes confusing assertion failures; always use strict equality in test asserts so no hidden coercion happens."}]}},54916,(e,n,t)=>{n.exports={description:"Conditionals and loops for test logic.",questions:[{id:1,question:"How does an if / else if / else chain decide which branch runs?",answer:"JavaScript evaluates conditions top to bottom and runs the first block whose condition is truthy. Once one branch runs, the rest of the chain is skipped, and if none match, the else block runs.\n\ncode:\nconst status = 200;\nif (status >= 500) console.log('server error');\nelse if (status === 404) console.log('not found');\nelse console.log('ok');\n\nreal example:\nMapping HTTP status codes to readable failure messages in API tests keeps assertion output meaningful instead of a raw number."},{id:2,question:"What is the ternary operator and when should you use it?",answer:"The ternary operator condition ? a : b evaluates to a when the condition is truthy and b otherwise. Use it for short assignments, but prefer if/else when the logic is longer than one line.\n\ncode:\nconst expected = page.isVisible() ? 'visible' : 'hidden';\n\nreal example:\nBuilding per-browser config with const headed = process.env.CI ? false : true keeps one-liner branching readable inside Playwright projects."},{id:3,question:"What happens when a switch case block has no break statement?",answer:"Execution falls through to the next case until a break or the end of the switch is reached, even if the later conditions do not match.\n\ncode:\nconst x = 2;\nswitch (x) {\n  case 1: console.log('one');\n  case 2: console.log('two');\n  default: console.log('fallthrough');\n}\n\nreal example:\nForgetting break in a browser-detection switch in shared test setup runs every case after the match, causing double execution and flaky state."},{id:4,question:"How does the for loop with let differ from one with var in terms of iteration variables?",answer:"The let keyword creates a fresh binding for each iteration, so callbacks capture each loop value correctly. With var there is one shared binding, so callbacks see the final value.\n\ncode:\nfor (let i = 0; i < 3; i++) {\n  setTimeout(() => console.log(i), 0);  // 0 1 2\n}\nfor (var j = 0; j < 3; j++) {\n  setTimeout(() => console.log(j), 0);  // 3 3 3\n}\n\nreal example:\nRegistering multiple page.waitForEvent callbacks in a loop requires let so each callback checks the correct network request."},{id:5,question:"What is the purpose of break and continue in loops?",answer:"break exits the loop immediately, while continue skips the rest of the current iteration and moves to the next one.\n\ncode:\nfor (const n of [1, 2, 3, 4]) {\n  if (n === 2) continue;\n  if (n === 4) break;\n  console.log(n);  // 1 3\n}\n\nreal example:\nIterating test users you can skip disabled fixtures with continue and stop scanning once the target user is found with break."},{id:6,question:"What is the difference between for...of and for...in?",answer:"for...of iterates over values of arrays, strings, and other iterables. for...in iterates over enumerable property keys of an object, and it is not meant for array iteration.\n\ncode:\nconst arr = ['a', 'b'];\nfor (const v of arr) console.log(v);            // a b\nconst obj = { a: 1, b: 2 };\nfor (const k in obj) console.log(k, obj[k]);    // a 1 b 2\n\nreal example:\nUse for...of to walk page locator results from page.locator('.row').all() so each element is handled by value, never by accidental property key."},{id:7,question:"How many times does a do...while loop run at minimum?",answer:"A do...while loop always runs its body at least once because the condition is checked after the first iteration.\n\ncode:\nlet i = 0;\ndo {\n  console.log(i);\n  i++;\n} while (i < 3);\n\nreal example:\nAccepting at least one click attempt in a UI before checking a condition, such as dismissing a welcome modal, matches the guarantee of running once."},{id:8,question:"Why is checking if (count) risky when count could be 0?",answer:"Zero is falsy, so if (count) treats a legitimate zero as an empty or missing value. The block is skipped even though 0 might be a valid state.\n\ncode:\nconst cartCount = 0;\nif (cartCount) {\n  console.log('has items');\n} else {\n  console.log('no items');  // runs\n}\n\nreal example:\nAsserting cart behavior with if (count) would skip zero-item scenarios; compare explicitly with count === 0 when zero matters."},{id:9,question:"What does a while loop do when its condition never becomes falsy?",answer:"It loops forever, which freezes or crashes the test process. The condition must eventually evaluate to false, or you need an explicit break.\n\ncode:\n// let i = 0;\n// while (true) { i++; }  // infinite loop\n\nreal example:\nCustom wait loops such as waiting for an element to disappear must include a timeout and break, otherwise a missing element hangs the suite."},{id:10,question:"How do you loop over both keys and values of an object?",answer:"Use Object.entries() to get an array of [key, value] pairs, then destructure them in a for...of loop.\n\ncode:\nconst config = { retries: 2, timeout: 5000 };\nfor (const [key, value] of Object.entries(config)) {\n  console.log(key, value);\n}\n\nreal example:\nPrinting or asserting every entry in an API payload before sending it keeps dynamic request data visible in test logs."},{id:11,question:"What is short-circuit evaluation in conditionals?",answer:"In an && chain, evaluation stops at the first falsy value; in an || chain, it stops at the first truthy value. Later branches never run once the result is decided.\n\ncode:\nconst user = login() && fetchProfile();\nconst fallback = env.RUN || 'local';\n\nreal example:\nGuarding with element && element.textContent avoids errors on null locator results while making sure the text extraction only runs when the element exists."},{id:12,question:"What is the purpose of labeled statements with break?",answer:"A label renames a loop so break and continue can target an outer loop instead of only the innermost one.\n\ncode:\nouter: for (const a of [1, 2]) {\n  for (const b of [1, 2]) {\n    if (b === 2) break outer;\n    console.log(a, b);\n  }\n}\n\nreal example:\nScanning a matrix of test environments for the first failing combination and stopping all looping is cleaner with a named outer label."},{id:13,question:"How do you iterate over the characters of a string?",answer:"A for...of loop visits each character by value, including emoji, while indexing by position can split surrogate pairs.\n\ncode:\nfor (const ch of 'abc') {\n  console.log(ch);  // a b c\n}\n\nreal example:\nValidating that every character of an order code is a digit uses a for...of loop over the code string before asserting against the alphanumeric rule."},{id:14,question:"What is the difference between a for loop and forEach on an array?",answer:"The for loop can use break and continue and control the index. forEach calls a callback for every element and cannot be stopped early except by throwing.\n\ncode:\nfor (const [i, item] of arr.entries()) {\n  if (i > 2) break;\n}\narr.forEach((item, i) => console.log(i, item));\n\nreal example:\nUse a for...of loop when scanning locator lists and stopping on the first failing row; forEach would need an exception to stop."},{id:15,question:"What does an empty condition in a for loop mean such as for (;;)?",answer:"All three clauses are optional, so for (;;) has an always-true condition and loops forever until a break, return, or exception exits it.\n\ncode:\nlet i = 0;\nfor (;;) {\n  i++;\n  if (i === 3) break;\n}\n\nreal example:\nRetry helpers sometimes use for (;;) as a deliberate infinite loop guarded by a count limit and break, making the exit logic explicit."}]}},51010,(e,n,t)=>{n.exports={description:"String methods and template literals.",questions:[{id:1,question:"How do you get the length of a string?",answer:"The length property returns the number of UTF-16 code units in the string, which matches the visible character count for most text.\n\ncode:\nconsole.log('playwright'.length);  // 10\n\nreal example:\nTruncating long failure messages in test reporters by checking .length before slicing keeps logs readable without hard crashes."},{id:2,question:"What is the difference between indexOf and includes on a string?",answer:"includes returns a boolean for whether the substring exists, while indexOf returns the first position or -1 when not found.\n\ncode:\nconsole.log('video/invoice'.includes('invoice'));  // true\nconsole.log('video/invoice'.indexOf('invoice'));   // 6\n\nreal example:\nAsserting that a redirect URL contains the expected route with expect(url).toContain('/checkout') is a common Playwright pattern."},{id:3,question:"What does slice do and how does it differ from substring?",answer:"slice returns a portion of the string by start and end index. Both treat negative arguments as counting from the end, but substring clamps negatives to 0, making slice more predictable.\n\ncode:\nconsole.log('trader'.slice(1, 4));   // ra\nconsole.log('trader'.slice(-2));     // er\n\nreal example:\nExtracting a slug from a URL segment with slice keeps the parsing deterministic even when the segment length varies."},{id:4,question:"Why should you always call trim() on text scraped from a page?",answer:"trim removes leading and trailing whitespace, and scraped text often contains newlines or padding. Comparing untrimmed text causes assertions to fail on invisible characters.\n\ncode:\nconst text = '  Login  ';\nconsole.log(text.trim());  // 'Login'\n\nreal example:\nPlaywright assertions like await expect(page.getByText('Login')).toBeVisible() can fail because textContent includes formatting whitespace that trim() removes."},{id:5,question:"How do you convert a string to uppercase or lowercase?",answer:"Use toUpperCase() or toLowerCase(), both of which return new strings because strings are immutable.\n\ncode:\nconsole.log('login'.toUpperCase());  // 'LOGIN'\nconsole.log('LOGIN'.toLowerCase());  // 'login'\n\nreal example:\nCase-insensitive assertions normalize both sides with toLowerCase() before comparing user-facing text like country names or error messages."},{id:6,question:"What does split do and what does join do?",answer:"split divides a string into an array by a separator, and join merges an array back into a string with a separator.\n\ncode:\nconst parts = 'a,b,c'.split(',');\nconsole.log(parts);                 // ['a','b','c']\nconsole.log(parts.join('-'));       // 'a-b-c'\n\nreal example:\nParsing a comma-separated tags header or building CSV test fixtures are both natural split and join workflows."},{id:7,question:"What is the difference between replace and replaceAll?",answer:"replace substitutes only the first match, while replaceAll substitutes every match. Passing a regex with the global flag also replaces all matches.\n\ncode:\nconsole.log('a-b-a'.replace('-', '_'));      // 'a_b-a'\nconsole.log('a-b-a'.replaceAll('-', '_'));   // 'a_b_a'\n\nreal example:\nSanitizing an API ID that may contain multiple dashes with replaceAll prevents partial replacements from breaking downstream selectors."},{id:8,question:"How do template literals interpolate values?",answer:"Template literals use backticks and embed values with ${expression}, where any JavaScript expression is evaluated and converted to a string.\n\ncode:\nconst name = 'Ana';\nconsole.log(`Hello, ${name}!`);  // Hello, Ana!\n\nreal example:\nBuilding dynamic locators like page.getByText(`Order #${orderId}`) reads far better than string concatenation with plus signs."},{id:9,question:"How do you check if a string starts or ends with a given substring?",answer:"Use startsWith and endsWith, which return booleans and are case-sensitive by default.\n\ncode:\nconst url = 'https://api.test.com/v1';\nconsole.log(url.startsWith('https://'));  // true\nconsole.log(url.endsWith('/v1'));         // true\n\nreal example:\nValidating API base URLs and env-specific endpoints before tests hit them avoids sending requests to the wrong host."},{id:10,question:"What does padStart do?",answer:"padStart fills the beginning of a string with a filler until it reaches a target length, which is useful for padding ids and timestamps.\n\ncode:\nconsole.log('42'.padStart(5, '0'));  // '00042'\n\nreal example:\nGenerating deterministic test order numbers with fixed digit counts keeps parallel test data readable in dashboards."},{id:11,question:"Are strings mutable or immutable in JavaScript?",answer:"Strings are immutable. Every string method that changes content returns a brand-new string, and the original value stays untouched.\n\ncode:\nconst s = 'hello';\nconst u = s.toUpperCase();\nconsole.log(s);  // 'hello'\nconsole.log(u);  // 'HELLO'\n\nreal example:\nWhen storing original page text and a transformed copy, immutability guarantees the asserted original is never corrupted by transforms."},{id:12,question:"What is the difference between charAt and bracket indexing?",answer:"charAt('hello'.charAt(0)) returns the character or an empty string when out of range, while bracket indexing returns undefined for missing positions.\n\ncode:\nconsole.log('hello'.charAt(9));  // ''\nconsole.log('hello'[9]);         // undefined\n\nreal example:\nBracket indexing that returns undefined is a common source of hidden bugs when assertion messages interpolate a missing character."},{id:13,question:"How do you write multi-line strings without escape sequences?",answer:"Template literals with backticks preserve real newlines, so you can write multi-line text directly without escaping newline characters.\n\ncode:\nconst message = `Line one\nLine two`;\nconsole.log(message);\n\nreal example:\nMulti-line request bodies and SQL fixtures in tests stay readable, which helps code review catch wrong assertions faster."},{id:14,question:"What is the difference between innerText and textContent reminders for scraped text?",answer:"textContent returns every text node including hidden elements and preserves whitespace, while innerText reflects what is visually rendered. Automation scrapers almost always want the trimmed textContent.\n\ncode:\nconst node = document.getElementById('total');\nconst raw = node.textContent.trim();\n\nreal example:\nCypress text assertions use .invoke('text') which reads textContent, so comparing against innerText expectations produces mismatches."},{id:15,question:"How do you convert a string to an array of characters?",answer:"Use split('') with an empty separator, or the Array.from() function which also handles unicode correctly.\n\ncode:\nconsole.log('abc'.split(''));    // ['a','b','c']\nconsole.log(Array.from('abc')); // ['a','b','c']\n\nreal example:\nReversing a code and checking it against an expected layout uses character arrays that make each digit individually assertable."}]}},95907,(e,n,t)=>{n.exports={description:"Functions, arrow functions, scope and closures.",questions:[{id:1,question:"What is the difference between a function declaration and a function expression?",answer:"A declaration starts with the function keyword and is hoisted, so it can be called before its line of definition. An expression assigns a function to a variable and is not hoisted, so it must be defined before use.\n\ncode:\nconsole.log(add(1, 2));\nfunction add(a, b) { return a + b; }\n\nconst mul = (a, b) => a * b;\nconsole.log(mul(2, 3));\n\nreal example:\nHelpers defined with declarations at the bottom of a test file still work, but arrow helpers must appear before their first call or the suite errors."},{id:2,question:"What does a function return if it has no return statement?",answer:"It returns undefined implicitly. The value undefined is also returned when return is written with no expression after it.\n\ncode:\nfunction noop() {}\nconsole.log(noop());  // undefined\n\nreal example:\nMap callbacks that forget a return produce undefined entries, so a map over locator texts without a return yields an array of undefined values."},{id:3,question:"What are default parameters and how do they behave with undefined?",answer:"Default parameters kick in only when the argument is undefined or omitted, not when it is null. They let functions support optional configuration.\n\ncode:\nfunction wait(ms = 1000) { return ms; }\nconsole.log(wait());         // 1000\nconsole.log(wait(undefined)); // 1000\nconsole.log(wait(null));      // null\n\nreal example:\nPlaywright helper functions with defaults like a standard timeout make tests readable when the caller only overrides some options."},{id:4,question:"What is a rest parameter and how is it used?",answer:"A rest parameter collects the remaining arguments into an array, written as ...args in the parameter list. It replaces the old arguments object.\n\ncode:\nfunction total(...nums) {\n  return nums.reduce((sum, n) => sum + n, 0);\n}\nconsole.log(total(1, 2, 3));  // 6\n\nreal example:\nWrapper functions that forward variable arguments to Playwright methods, like fillForm(...values), forward each call unmodified."},{id:5,question:"What is the difference between arrow functions and regular functions?",answer:"Arrow functions are concise, do not have their own this or the arguments object, and inherit the surrounding scope. Regular functions get their own dynamic this determined by how they are called.\n\ncode:\nconst arrow = () => this;\nfunction regular() { return this; }\n\nreal example:\nIn class-based page objects, arrow methods keep this pointing at the instance so queue and waitForEvent callbacks work in Playwright."},{id:6,question:"What is lexical this and why do arrows use it?",answer:"Lexical this means the arrow uses the this value from the surrounding scope where it was defined, not where it is called. This removes the need for callbacks to bind this manually.\n\ncode:\nconst obj = {\n  count: 0,\n  next() {\n    setTimeout(() => {\n      this.count++;\n      console.log(this.count);\n    }, 0);\n  },\n};\n\nreal example:\nInside page.evaluate callbacks and event listeners, arrows capture the test context so shared state like a counter or request log updates correctly."},{id:7,question:"What is a closure?",answer:"A closure is a function that remembers the variables from the scope where it was created, even after that outer function has returned. It gives functions private persistent state.\n\ncode:\nfunction makeCounter() {\n  let count = 0;\n  return () => ++count;\n}\nconst c = makeCounter();\nconsole.log(c(), c(), c());  // 1 2 3\n\nreal example:\nGenerating unique test usernames with a factory guarantees no two fixtures collide in a parallel run."},{id:8,question:"What is the difference between global scope, function scope, and block scope?",answer:"Global scope is visible everywhere. Function scope applies to var and function declarations, visible inside the whole function. Block scope applies to let and const, visible only inside the nearest braces.\n\ncode:\nif (true) {\n  let x = 1;\n  var y = 2;\n}\nconsole.log(y);  // 2\n// console.log(x);  // ReferenceError\n\nreal example:\nLoop counters with let stay scoped to each invocation, so parallel-retry state never leaks across iterations."},{id:9,question:"What is an IIFE and why is it used?",answer:"An Immediately Invoked Function Expression runs as soon as it is defined, giving code its own private scope immediately. It prevents variables from leaking into the global scope.\n\ncode:\n(function () {\n  const setup = 'private';\n  console.log('ran once');\n})();\n\nreal example:\nSnippet tools and old modules wrap initialization in an IIFE so helper constants cannot collide with test globals."},{id:10,question:"What is a higher-order function?",answer:"A higher-order function takes a function as an argument, returns a function, or both. Methods like map, filter, and forEach are higher-order functions.\n\ncode:\nfunction applyTwice(fn, value) {\n  return fn(fn(value));\n}\nconsole.log(applyTwice(x => x * 3, 2));  // 18\n\nreal example:\nBuilding a beforeAll hook that wraps setup in a higher-order retry lets every test reuse robust initialization."},{id:11,question:"What is a callback function?",answer:"A callback is a function passed into another function to be invoked later, often after some work completes. Callbacks are how timers, events, and async operations get their result handling.\n\ncode:\nsetTimeout(() => console.log('later'), 1000);\nusers.forEach(u => console.log(u.name));\n\nreal example:\nplaywright library page.on('requestfailed', cb) registers callbacks to observe failed requests during a test run."},{id:12,question:"What is callback hell and how is it solved?",answer:"Callback hell is deeply nested asynchronous callbacks that become unreadable and hard to debug. It is solved by promises chaining with then and finally by async/await.\n\ncode:\napiCall(data)\n  .then(r => apiCall2(r))\n  .then(r2 => apiCall3(r2));\n\nreal example:\nSequential API setup for login, then item creation, then checkout reads top to bottom with await instead of five levels of nesting."},{id:13,question:"How do you handle a variable number of arguments without rest parameters?",answer:"The arguments object inside a regular function holds all passed arguments. It is array-like and lacks array methods, so convert it with Array.from when needed.\n\ncode:\nfunction max() {\n  return Math.max(...arguments);\n}\nconsole.log(max(1, 5, 3));  // 5\n\nreal example:\nArrow functions do not have arguments, so team code that still uses them in callbacks might leak the outer arguments object accidentally."},{id:14,question:"What does it mean that functions are first-class citizens in JavaScript?",answer:"Functions can be stored in variables, passed as arguments, returned from other functions, and manipulated like any other value.\n\ncode:\nconst fn = function () { return 1; };\nconst runner = f => f() + 1;\nconsole.log(runner(fn));  // 2\n\nreal example:\nPassing a polling predicate like page.waitForFunction(myCheck) naturalizes assertions as plain function values."},{id:15,question:"How do you build a function that returns a function, and what is it good for?",answer:"Returning a function from a function creates factories that preconfigure behavior, useful for defaults and partial application.\n\ncode:\nfunction greeter(prefix) {\n  return name => `${prefix} ${name}`;\n}\nconst hi = greeter('Hello');\nconsole.log(hi('Ana'));  // Hello Ana\n\nreal example:\nA selector factory returning a locator builder with a fixed data-testid prefix keeps page object helpers DRY."},{id:16,question:"What is the difference between an arrow function's implicit and explicit return?",answer:"Arrow functions with a single expression return it implicitly without braces. Once you add curly braces you must write an explicit return statement.\n\ncode:\nconst square = x => x * x;\nconst squareBlock = x => { return x * x; };\n\nreal example:\nA map callback written with braces but no return yields undefined for every element, so check quickly when extracted column data is empty."}]}},12877,(e,n,t)=>{n.exports={description:"Arrays, map/filter/reduce and the key methods.",questions:[{id:1,question:"What is the difference between push and unshift?",answer:"push adds one or more elements to the end of an array, while unshift adds them to the beginning. Both mutate the original array and return the new length.\n\ncode:\nconst arr = [2];\narr.push(3);\narr.unshift(1);\nconsole.log(arr);  // [1, 2, 3]\n\nreal example:\nBuilding an ordered list of test steps by appending with push keeps the execution order natural and easy to assert."},{id:2,question:"What is the difference between pop and shift?",answer:"pop removes and returns the last element, and shift removes and returns the first element. Both mutate the array in place.\n\ncode:\nconst arr = [1, 2, 3];\nconsole.log(arr.pop());   // 3\nconsole.log(arr.shift()); // 1\nconsole.log(arr);         // [2]\n\nreal example:\nMaintaining an undo stack in test helpers with pop mirrors a last-in-first-out history of UI actions."},{id:3,question:"What does splice do and how is it different from slice?",answer:"splice mutates the array, adding or removing elements at an index, and returns the removed elements. slice returns a new non-mutating copy of a range.\n\ncode:\nconst a = [1, 2, 3, 4];\nconsole.log(a.splice(1, 2));  // [2, 3]\nconsole.log(a);               // [1, 4]\nconst b = [1, 2, 3, 4];\nconsole.log(b.slice(1, 3));   // [2, 3]\nconsole.log(b);               // [1, 2, 3, 4]\n\nreal example:\nRemoving a test item from a shared fixture array uses splice, while previewing a subset safely uses slice."},{id:4,question:"How do you copy an array without sharing a reference?",answer:"Use the spread operator [...arr] or slice(). Both create a new array so later mutations of the copy do not affect the original.\n\ncode:\nconst original = [1, 2];\nconst copy = [...original];\ncopy.push(3);\nconsole.log(original);  // [1, 2]\n\nreal example:\nSorting a locator result set with [...items].sort() keeps the original DOM order intact for other assertions."},{id:5,question:"What does map return and when should you use it?",answer:"map transforms every element with a callback and returns a new array of the same length. Use it when you need the transformed result, not just side effects.\n\ncode:\nconst ids = ['b1', 'b2'].map(id => `#${id}`);\nconsole.log(ids);  // ['#b1', '#b2']\n\nreal example:\nMapping API user objects to names or ids turns a bulk response into an assertable list of string values."},{id:6,question:"What does filter return and how do you chain it with map?",answer:"filter returns a new array with only elements where the callback returns true, and it can be chained with map to select then transform.\n\ncode:\nconst users = [{ name: 'Ana', active: true }, { name: 'Bob', active: false }];\nconst names = users.filter(u => u.active).map(u => u.name);\nconsole.log(names);  // ['Ana']\n\nreal example:\nSelecting only enabled test users from a fixture list before running the deposit check avoids false failures on disabled accounts."},{id:7,question:"What is the difference between find and filter?",answer:"find returns the first element matching the predicate, or undefined when none match. filter returns an array of all matching elements.\n\ncode:\nconst nums = [4, 7, 9];\nconsole.log(nums.find(n => n > 5));  // 7\nconsole.log(nums.filter(n => n > 5)); // [7, 9]\n\nreal example:\nLooking up a single user by id with find, then asserting properties on it, is the standard API response pattern."},{id:8,question:"What do some and every return?",answer:"some returns true if at least one element passes the predicate, and every returns true only if all elements pass. Both short-circuit early and return booleans.\n\ncode:\nconst scores = [90, 99, 100];\nconsole.log(scores.some(s => s < 95));   // true\nconsole.log(scores.every(s => s >= 90));  // true\n\nreal example:\nAudit style assertions like expect(rows.every(r => r.invoice)).toBe(true) verify a whole table column in one expression."},{id:9,question:"What does reduce do and how does its accumulator work?",answer:"reduce folds an array into a single value using a callback and an initial accumulator. The callback's return becomes the accumulator for the next step.\n\ncode:\nconst total = [10, 20, 5].reduce((sum, n) => sum + n, 0);\nconsole.log(total);  // 35\n\nreal example:\nCounting test results by status with reduce builds an object like { passed: 12, failed: 2 } for the summary report."},{id:10,question:"Why is the initial value important in reduce?",answer:"Without an initial value, reduce uses the first element as the accumulator and starts from the second element. For some callbacks, such as summing with addition, the result can differ or error on empty arrays.\n\ncode:\nconsole.log([].reduce((a, b) => a + b));  // TypeError: empty array\nconsole.log([] .reduce((a, b) => a + b, 0));  // 0\n\nreal example:\nAlways pass 0 or an expected object as the seed so group-by counters behave identically when a query returns zero rows."},{id:11,question:"What is the difference between forEach and map?",answer:"forEach runs a callback for each element and returns undefined, while map builds and returns a new array of callback results. Use map when you need the result.\n\ncode:\nconst result = [1, 2].forEach(n => n * 2);\nconsole.log(result);  // undefined\n\nreal example:\nLogging each request from a list is a forEach job, but producing an array of request bodies for assertions needs map."},{id:12,question:"How does sort behave by default and how do you sort numbers?",answer:"Default sort converts elements to strings and sorts lexicographically, so 10 comes before 2. Numeric sorting requires a comparator like (a, b) => a - b.\n\ncode:\nconsole.log([10, 2, 1].sort());             // [1, 10, 2]\nconsole.log([10, 2, 1].sort((a, b) => a - b)); // [1, 2, 10]\n\nreal example:\nSorting API pagination numbers or timestamps needs an explicit comparator, otherwise assertions on ordering fail mysteriously."},{id:13,question:"What does includes do on an array?",answer:"includes checks whether an array contains a given primitive value using strict equality and returns a boolean.\n\ncode:\nconsole.log(['admin', 'editor'].includes('admin'));  // true\n\nreal example:\nAsserting that a permissions array returned by an API contains the expected role is a one-line role-based test."},{id:14,question:"What is the difference between indexOf and findIndex?",answer:"indexOf finds the position of a primitive value by equality, while findIndex finds the position of the first element matching a predicate function. Both return -1 when nothing matches.\n\ncode:\nconst items = [{ id: 3 }, { id: 7 }];\nconsole.log(items.findIndex(x => x.id === 7));  // 1\n\nreal example:\nUpdating or removing the row that matches a predicate requires its index, which findIndex supplies."},{id:15,question:"What does flat do and what does it mean to flatten nested arrays?",answer:"flat concatenates nested arrays up to a given depth into a single-level array, returning a new array without mutating the input.\n\ncode:\nconsole.log([[1, 2], [3, [4]]].flat(2));  // [1, 2, 3, 4]\n\nreal example:\nFlattening paginated API responses into one flat list of records makes counting total items across pages trivial."},{id:16,question:"How do you check if an array is empty before processing it?",answer:"Compare against .length or use the truthiness of the array itself, since an empty array is truthy but has length 0.\n\ncode:\nconst rows = [];\nif (rows.length === 0) console.log('no data');\n\nreal example:\nGuard a for...of over locator results with a length check so a missing table does not silently promise and then fail later assertions."}]}},60349,(e,n,t)=>{n.exports={description:"Objects, destructuring and optional chaining.",questions:[{id:1,question:"How do you create an object and read its properties?",answer:"Objects are created with curly braces and read with dot notation for known keys or bracket notation for dynamic keys.\n\ncode:\nconst user = { name: 'Ana', age: 30 };\nconsole.log(user.name);\nconst key = 'age';\nconsole.log(user[key]);  // 30\n\nreal example:\nReading fields off an API response like res.body.checkout.total is nothing more than chained dot notation."},{id:2,question:"How do you add or update a property on an existing object?",answer:"Assign to the property with dot or bracket notation. Assigning to a new key adds it, and to an existing key overwrites it.\n\ncode:\nconst user = {};\nuser.name = 'Ana';\nuser['age'] = 30;\nconsole.log(user);  // { name: 'Ana', age: 30 }\n\nreal example:\nMerging runtime data into a base request body by assignment keeps API fixtures flexible per test."},{id:3,question:"How do you list the keys, values, and entries of an object?",answer:"Object.keys returns an array of keys, Object.values returns the values, and Object.entries returns pairs as arrays.\n\ncode:\nconst cfg = { retries: 2, tag: 'smoke' };\nconsole.log(Object.keys(cfg));    // ['retries', 'tag']\nconsole.log(Object.values(cfg));  // [2, 'smoke']\nconsole.log(Object.entries(cfg)); // [['retries', 2], ['tag', 'smoke']]\n\nreal example:\nWrapping a config in Object.entries lets a test iterate flags as pairs and assert every known setting in one loop."},{id:4,question:"How do you check if an object has a property?",answer:"Use the in operator, hasOwnProperty, or Object.hasOwn to check for a key regardless of its value, since the value could be undefined.\n\ncode:\nconst user = { name: 'Ana' };\nconsole.log('name' in user);            // true\nconsole.log(Object.hasOwn(user, 'x'));  // false\n\nreal example:\nValidating that a login response includes a token before reading it avoids accessing a missing field."},{id:5,question:"How does the spread operator copy and merge objects?",answer:"Spreading an object copies its enumerable properties into a new object, so spread order decides which keys win when merging.\n\ncode:\nconst base = { browser: 'chromium', headless: true };\nconst override = { headless: false };\nconst config = { ...base, ...override };\nconsole.log(config);  // { browser: 'chromium', headless: false }\n\nreal example:\nMerging default launch options with per-test overrides keeps shared config clean."},{id:6,question:"What is object destructuring and how do you rename keys?",answer:"Destructuring unpacks properties into variables, and renaming uses key: newName syntax.\n\ncode:\nconst user = { name: 'Ana', age: 30 };\nconst { name: userName, age } = user;\nconsole.log(userName, age);  // Ana 30\n\nreal example:\nPulling response fields into local names like const { data: payload } = res avoids later dot-chaining."},{id:7,question:"How do you provide default values during destructuring?",answer:"Defaults apply when the property is undefined, written as { missing = defaultValue }, and they do not apply when the value is null.\n\ncode:\nconst cfg = {}\nconst { timeout = 5000 } = cfg;\nconsole.log(timeout);  // 5000\n\nreal example:\nReading an optional field like total from a response while defaulting to 0 lets assertions run without crashes."},{id:8,question:"What is the rest pattern in destructuring?",answer:"The rest pattern collects remaining properties into a new object using ... in a destructuring assignment.\n\ncode:\nconst { name, ...details } = { name: 'Ana', age: 30, role: 'admin' };\nconsole.log(name);     // Ana\nconsole.log(details);  // { age: 30, role: 'admin' }\n\nreal example:\nOmitting a password field from a logged user object before asserting it keeps secrets out of output."},{id:9,question:"What is optional chaining and how does it prevent errors?",answer:"Optional chaining with ?. returns undefined instead of throwing when a property in the chain is null or undefined.\n\ncode:\nconst res = {};\nconsole.log(res.body?.user?.name);  // undefined, no error\n\nreal example:\nReading nested API data like data.items[0]?.total skips fragile guard checks."},{id:10,question:"When does optional chaining stop and what does ?.() do?",answer:"Optional chaining short-circuits the rest of the chain at the first null or undefined. The ?.() form checks a function exists before calling it.\n\ncode:\nconst cb = null;\ncb?.();  // no error\n\nreal example:\nCalling an optional teardown hook only when a fixture defined it keeps cleanup robust."},{id:11,question:"What is the difference between shallow and deep copy?",answer:"A shallow copy duplicates the top level but shares nested objects by reference, while a deep copy replicates all nested levels.\n\ncode:\nconst a = { x: { y: 1 } };\nconst shallow = { ...a };\nshallow.x.y = 2;\nconsole.log(a.x.y);  // 2\n\nreal example:\nCopying test config with nested objects silently shares them, causing cross-test mutation."},{id:12,question:"How do you deep copy an object in plain JavaScript?",answer:"structuredClone is the modern deep copy, while JSON.parse(JSON.stringify(obj)) works for JSON-safe values.\n\ncode:\nconst copy = structuredClone(original);\nconst jsonCopy = JSON.parse(JSON.stringify(original));\n\nreal example:\nCloning payload fixtures before mutating keeps the original test data intact across runs."},{id:13,question:"What are computed property names in object literals?",answer:"Computed property names use square brackets inside the literal so the key is evaluated as an expression at creation time.\n\ncode:\nconst key = 'role'\nconst obj = { [key]: 'admin' };\nconsole.log(obj.role);  // admin\n\nreal example:\nMapping environment variables into a test config object uses computed keys for dynamic settings."},{id:14,question:"How do object methods and the this keyword interact?",answer:"A method defined in an object gets this bound to the object when called as obj.method(), but the binding is lost when the method is passed as a bare reference.\n\ncode:\nconst counter = {\n  n: 0,\n  inc() { this.n++; }\n};\ncounter.inc();\nconsole.log(counter.n);  // 1\n\nreal example:\nPlaywright page objects rely on this staying bound inside methods, so arrow wrappers are used in callbacks."}]}},43492,(e,n,t)=>{n.exports={description:"Map, Set and other ES6 collections.",questions:[{id:1,question:"What is a Map and how does it differ from a plain object?",answer:"A Map is a key-value collection that accepts any key type, preserves insertion order, and provides clean methods. Plain objects only accept string and symbol keys and inherit prototype properties.\n\ncode:\nconst m = new Map();\nm.set('user', 'Ana');\nm.set(1, 'number key');\nconsole.log(m.get('user'));  // Ana\n\nreal example:\nMapping response status codes to enums is safer in a Map because numeric keys behave predictably."},{id:2,question:"What are the main methods on a Map?",answer:"A Map supports set, get, has, delete, clear, and the size property. It is iterated with for...of and supports forEach.\n\ncode:\nconst m = new Map([['a', 1]]);\nm.set('b', 2);\nconsole.log(m.has('a'));  // true\nconsole.log(m.size);      // 2\nm.delete('a');\n\nreal example:\nTracking per-request assertions with a Map keyed by URL lets a test verify each endpoint result individually."},{id:3,question:"How do you iterate over a Map?",answer:"destructuring with for...of yields key-value pairs, and the keys, values, and entries methods return iterators.\n\ncode:\nconst m = new Map([['x', 1], ['y', 2]]);\nfor (const [key, value] of m) {\n  console.log(key, value);\n}\n\nreal example:\nIterating config maps in a test data setup prints each case name and payload for easy debugging of failures."},{id:4,question:"When should you choose a Map over an object?",answer:"Choose a Map when keys are not strings, when inserts happen frequently, when insertion order matters, or when you need easy size and deletion semantics.\n\ncode:\nconst cache = new Map();\nuserIds.forEach((id, i) => cache.set(id, i));\n\nreal example:\nCaching unique request timestamps by id benefits from Map's clean has and delete that objects lack natively."},{id:5,question:"What is a Set and what is it used for?",answer:"A Set holds unique values of any type and ignores duplicates. Adding an existing value keeps a single copy.\n\ncode:\nconst s = new Set([1, 2, 2, 3]);\nconsole.log([...s]);  // [1, 2, 3]\n\nreal example:\nDeduplicating an array of order ids before counting them uses a Set, turning a list into unique values in one line."},{id:6,question:"What are the main methods on a Set?",answer:"Set provides add, has, delete, clear, and the size property, plus iteration in insertion order.\n\ncode:\nconst s = new Set();\ns.add('a');\nconsole.log(s.has('a'));  // true\nconsole.log(s.size);      // 1\n\nreal example:\nUniqueness assertions like expecting no duplicate currencies in a response use a Set to compare lengths."},{id:7,question:"How do you convert a Set back to an array?",answer:"Use the spread operator or Array.from, both of which produce an array of the Set values in insertion order.\n\ncode:\nconst s = new Set([1, 1, 2]);\nconsole.log([...s]);       // [1, 2]\nconsole.log(Array.from(s)); // [1, 2]\n\nreal example:\nExtracting unique roles from a user response then asserting the sorted array keeps results deterministic."},{id:8,question:"What is the difference between a Set and an array?",answer:"A Set only stores each value once, provides O(1) has checks, and does not support indexing or accessing by position. Arrays keep duplicates and allow index access.\n\ncode:\nconst arr = [1, 1, 2];\nconst set = new Set(arr);\nconsole.log(set.has(2));  // true (O(1) lookups)\n\nreal example:\nFor membership checks on large test datasets, a Set is faster than scanning an array with includes."},{id:9,question:"How do you remove duplicates from an array while preserving order?",answer:"Pass the array to a Set then spread it back; since Set iteration preserves insertion order, the deduplicated array keeps the order.\n\ncode:\nconst unique = [...new Set([3, 1, 3, 2, 1])];\nconsole.log(unique);  // [3, 1, 2]\n\nreal example:\nRemoving duplicate tags from a metadata array before sending it to an API prevents validation rejects."},{id:10,question:"What is the difference between a Map and a WeakMap?",answer:"A WeakMap only accepts object keys and holds weak references, so it does not prevent garbage collection. It has no size property and no iteration.\n\ncode:\nconst wm = new WeakMap();\nlet obj = { id: 1 };\nwm.set(obj, 'payload');\nobj = null;  // entry can be collected\n\nreal example:\nWeakMap is useful for attaching private per-object state in libraries, but test code generally prefers a regular Map for inspectability."},{id:11,question:"What is the difference between a Set and a WeakSet?",answer:"A WeakSet holds only object values with weak references, meaning it cannot hold primitives, has no size or iteration, and allows garbage collection of its objects.\n\ncode:\nconst ws = new WeakSet();\nlet obj = {};\nws.add(obj);\nconsole.log(ws.has(obj));  // true\n\nreal example:\nMarking DOM elements as visited in memory-sensitive scrapers uses WeakSet so removed nodes free memory automatically."},{id:12,question:"How do you find the union of two arrays using a Set?",answer:"Concatenate both arrays and pass the result into a Set, then spread it back to get all unique values from both.\n\ncode:\nconst a = [1, 2, 3];\nconst b = [3, 4];\nconsole.log([...new Set([...a, ...b])]);  // [1, 2, 3, 4]\n\nreal example:\nMerging permitted groups from two sources into one uniquified list drives the expected-permission assertion."},{id:13,question:"How do you compute the difference between two sets of strings?",answer:"Filter one array for values the other Set does not have, using the Set's fast has check as the predicate.\n\ncode:\nconst expected = new Set(['a', 'b']);\nconst actual = ['a'];\nconst missing = expected.values();\n[...expected].filter(x => !actual.includes(x));  // ['b']\n\nreal example:\nComparing a required-fields Set against keys actually present in a response surfaces which fields are missing in assertions."},{id:14,question:"Why is key order guaranteed in a Map but not for object keys?",answer:"A Map always iterates in insertion order. Object key order follows the spec: integer-like string keys sort first, then other strings in insertion order, then symbols.\n\ncode:\nconst m = new Map([[1, 'a'], ['x', 'b']]);\nconsole.log([...m.keys()]);  // [1, 'x'] insertion order\n\nreal example:\nWhen payload ordering matters for a probe request, a Map preserves the exact sequence objects cannot guarantee."},{id:15,question:"How do you initialize a Map and a Set with data in one line?",answer:"Both constructors accept an iterable: Map takes key-value pairs, and Set takes values directly.\n\ncode:\nconst m = new Map([['a', 1], ['b', 2]]);\nconst s = new Set(['red', 'green']);\n\nreal example:\nBuilding collections from API fixture arrays in a single line keeps test setup compact and reviewable."}]}},11603,(e,n,t)=>{n.exports={description:"JSON parsing/serialization and the fetch API.",questions:[{id:1,question:"What does JSON.parse do and when does it throw?",answer:'JSON.parse converts a JSON string into a JavaScript value. It throws a SyntaxError when the input is not valid JSON, including trailing commas or single quotes.\n\ncode:\nconst user = JSON.parse(\'{"name": "Ana"}\');\nconsole.log(user.name);  // Ana\n\nreal example:\nParsing a response body validates the server returned real JSON; a broken payload produces a SyntaxError you can catch and assert on.'},{id:2,question:"What does JSON.stringify do and what can it not encode?",answer:'JSON.stringify converts a JavaScript value into a JSON string. It omits functions, undefined, and symbols, and it throws on circular references or BigInt values.\n\ncode:\nconst s = JSON.stringify({ name: \'Ana\', fn: () => {} });\nconsole.log(s);  // {"name":"Ana"}\n\nreal example:\nSending API fixtures logs the wrapped object, and knowing functions are dropped explains surprising payloads in captured requests.'},{id:3,question:"How do you handle circular structures when serializing?",answer:"JSON.stringify throws TypeError: Converting circular structure to JSON. You must break the cycle or replace the deeply nested fields before serializing.\n\ncode:\nconst obj = { a: {} };\nobj.a.self = obj;\n// JSON.stringify(obj);  // throws\n\nreal example:\nPlaywright page objects sometimes hold references to the browser context; only send plain data objects when logging or posting them."},{id:4,question:"What is the replacer argument in JSON.stringify?",answer:"The replacer is a function or array that filters or transforms values during serialization, which can hide sensitive fields.\n\ncode:\nconst data = { user: 'Ana', token: 'secret' };\nconst safe = JSON.stringify(data, (key, value) =>\n  key === 'token' ? undefined : value\n);\nconsole.log(safe);  // {\"user\":\"Ana\"}\n\nreal example:\nLogging request payloads while stripping passwords or tokens avoids leaking secrets into CI logs."},{id:5,question:"What is the reviver argument in JSON.parse?",answer:"The reviver function transforms each parsed key-value pair, often converting date strings back into Date objects after parsing.\n\ncode:\nconst text = '{\"created\": \"2026-01-01T00:00:00Z\"}';\nconst obj = JSON.parse(text, (k, v) =>\n  k === 'created' ? new Date(v) : v\n);\nconsole.log(obj.created instanceof Date);  // true\n\nreal example:\nReviving timestamps lets tests assert date ordering directly instead of comparing ISO strings."},{id:6,question:"How do you make a GET request with the fetch API?",answer:"fetch(url) defaults to a GET request and returns a promise that resolves to a Response object. Call res.json() to read the body.\n\ncode:\nconst res = await fetch('https://api.test.com/users');\nconst users = await res.json();\nconsole.log(users[0].name);\n\nreal example:\nAPI smoke tests use fetch against a real backend, with assertions on res.status and the parsed body."},{id:7,question:"How do you send a POST request with a JSON body using fetch?",answer:"Pass an options object with method, headers, and a body stringified with JSON.stringify so the server receives proper JSON content.\n\ncode:\nconst res = await fetch('https://api.test.com/login', {\n  method: 'POST',\n  headers: { 'Content-Type': 'application/json' },\n  body: JSON.stringify({ user: 'admin', pass: 'secret' }),\n});\n\nreal example:\nAuth setup before UI steps posts a login request to create an authenticated session the browser then reuses."},{id:8,question:"Why must you convert the body with JSON.stringify before sending?",answer:"The fetch body must be a string, blob, form data, or similar. Passing an object directly causes a TypeError, so objects become JSON text first.\n\ncode:\n// fetch(url, { body: {a:1} })  // TypeError\nfetch(url, { body: JSON.stringify({ a: 1 }) });\n\nreal example:\nA common first bug in API tests is forgetting stringify, which crashes immediately with an unhelpful type error."},{id:9,question:"How do you check the HTTP status code from a fetch response?",answer:"The Response object exposes res.status and res.ok, where ok is true for status 200-299. fetch does not reject on 4xx or 5xx.\n\ncode:\nconst res = await fetch(url);\nconsole.log(res.status, res.ok);\nif (!res.ok) throw new Error(`HTTP ${res.status}`);\n\nreal example:\nAssertions like expect(res.status).toBe(200) work because fetch resolved even though a 404 is an error response."},{id:10,question:"What is the difference between res.json() and res.text()?",answer:"res.json() parses the body as JSON and returns the resulting value, while res.text() returns the raw body as a string. Both return promises and consume the response body.\n\ncode:\nconst data = await res.json();\nconst raw = await res.text();\n\nreal example:\nWhen a server returns an HTML error page, res.json() throws but res.text() lets you assert on the message inside it."},{id:11,question:"What happens when a fetch request itself fails, such as a network error?",answer:"fetch rejects with a TypeError only on network-level failures such as DNS errors or connection refused. HTTP errors still resolve, so you must check status yourself.\n\ncode:\ntry {\n  const res = await fetch('http://localhost:9999');\n} catch (err) {\n  console.log('network failure', err);\n}\n\nreal example:\nWrapping API calls in try/catch turns connection refused into a readable test failure instead of a generic crash."},{id:12,question:"How do you add a timeout to a fetch request?",answer:"Use an AbortController with AbortSignal.timeout, which rejects the request after the configured milliseconds.\n\ncode:\nconst res = await fetch(url, {\n  signal: AbortSignal.timeout(5000),\n});\n\nreal example:\nHanging endpoint calls in CI stall entire suites; a 10-second abort turns the delay into a quick, actionable failure."},{id:13,question:"How do you read response headers from a fetch response?",answer:"res.headers is a Headers object; use get or has to read specific header values.\n\ncode:\nconst res = await fetch(url);\nconsole.log(res.headers.get('content-type'));\n\nreal example:\nAsserting security headers like cache-control or content-type in API tests is done via the headers object."},{id:14,question:"How do you parallelize multiple API calls in a test?",answer:"Collect fetch promises in an array and await Promise.all, which runs them concurrently and returns results in order.\n\ncode:\nconst results = await Promise.all([\n  fetch('/a'),\n  fetch('/b'),\n]);\nconst data = await Promise.all(results.map(r => r.json()));\n\nreal example:\nChecking health of several endpoints before a suite starts finishes in the time of the slowest call instead of the sum."},{id:15,question:"How does Playwright's request API compare to using fetch directly?",answer:"Playwright request contexts reuse the browser's cookies and add retries, and the playwright library request fixture defaults to the baseURL automatically.\n\ncode:\nconst res = await request.get('/api/orders', {\n  headers: { Authorization: `Bearer ${token}` },\n});\nconst body = await res.json();\n\nreal example:\nUI tests that also call the API keep cookies in sync by using the built-in Playwright request fixture instead of raw fetch."}]}},3866,(e,n,t)=>{n.exports={description:"Promises, async/await and the event loop.",questions:[{id:1,question:"What are the three states of a Promise?",answer:"A promise is pending, fulfilled, or rejected. Once it settles into fulfilled or rejected, it stays in that state permanently.\n\ncode:\nconst p = new Promise((resolve, reject) => {\n  setTimeout(() => resolve('done'), 100);\n});\nconsole.log(p);  // pending at first\n\nreal example:\nPlaywright actions return promises that are pending until the browser answers, which is why awaiting them keeps state deterministic."},{id:2,question:"What is the purpose of then, catch, and finally on a promise?",answer:"then handles the fulfilled value, catch handles the rejection, and finally runs cleanup regardless of the outcome while passing the result through.\n\ncode:\nconst result = await fetch(url)\n  .then(res => res.json())\n  .catch(err => { throw new Error('fetch failed: ' + err); })\n  .finally(() => cleanup());\n\nreal example:\nMaking test setup that always closes a resource uses finally so failures still run post-test cleanup."},{id:3,question:"Why is Promise.all useful and what happens on rejection?",answer:"Promise.all resolves with an array of values when every promise fulfills, and rejects as soon as any single promise rejects, discarding the rest.\n\ncode:\nconst [a, b] = await Promise.all([fetch('/a'), fetch('/b')]);\n\nreal example:\nLoading two independent checkout endpoints in parallel cuts test time, and the earliest failure stops the suite early."},{id:4,question:"What is the difference between Promise.allSettled and Promise.all?",answer:"allSettled waits for every promise and reports each result as fulfilled or rejected, while all rejects immediately on the first failure.\n\ncode:\nconst results = await Promise.allSettled(urls.map(u => fetch(u)));\nresults.forEach(r => console.log(r.status));\n\nreal example:\nA multi-endpoint health check wants to log every failure, so allSettled is the right choice instead of all."},{id:5,question:"What does Promise.race do?",answer:"Promise.race settles as soon as the first promise settles, returning its value or reason while ignoring every other promise's outcome.\n\ncode:\nconst winner = await Promise.race([\n  request(),\n  timeout(5000),\n]);\n\nreal example:\nCapping a slow request with a timeout promise via race gives a quick failure instead of an endless client hang."},{id:6,question:"What is async/await and how does it improve on promise chains?",answer:"async/await makes promise-based code read like synchronous code. An async function returns a promise, and await unwraps a promise's value without nested callbacks.\n\ncode:\nasync function getUser() {\n  const res = await fetch('/user');\n  return res.json();\n}\n\nreal example:\nEvery Playwright test step such as page.click and expect is awaited, which is why test bodies are marked async."},{id:7,question:"What happens when you await a non-promise value?",answer:"await always returns the value directly for non-promises, wrapping it into an already-resolved promise internally. It adds no delay for plain values.\n\ncode:\nconst x = await 42;\nconsole.log(x);  // 42\n\nreal example:\nHelpers that sometimes return a promise and sometimes a plain value stay usable with await either way, which simplifies fixture functions."},{id:8,question:"How do you catch errors thrown inside an async function?",answer:"Wrap the awaited calls in try/catch, since an async function returns a rejected promise that the surrounding await or catch handles.\n\ncode:\nasync function run() {\n  try {\n    await riskyCall();\n  } catch (err) {\n    console.log('recovered:', err.message);\n  }\n}\n\nreal example:\nRetry logic catches transient network errors on login and retries a bounded number of times instead of failing instantly."},{id:9,question:"What is the event loop in JavaScript?",answer:"The event loop is the mechanism that processes the call stack and the message queue, running JavaScript's single thread while letting async callbacks execute in order.\n\ncode:\nconsole.log('start');\nsetTimeout(() => console.log('timeout'), 0);\nconsole.log('end');  // start, end, timeout\n\nreal example:\nKnowing that timers run after the current script explains why an immediate check after page.click still needs an await."},{id:10,question:"What is the difference between a microtask and a macrotask?",answer:"Microtasks such as promise callbacks run before the next macrotask such as setTimeout or an event handler. Between macrotasks the microtask queue is fully drained.\n\ncode:\nPromise.resolve().then(() => console.log('micro'));\nsetTimeout(() => console.log('macro'), 0);\nconsole.log('sync');  // sync, micro, macro\n\nreal example:\nThe ordering sync, then promise, then timer explains surprising log sequences and flaky timeout assumptions in tests."},{id:11,question:"Why do promises run before setTimeout callbacks?",answer:"Promise reactions are microtasks drained until empty right after the current synchronous code, while setTimeout callbacks are macrotasks scheduled for later task turns.\n\ncode:\nPromise.resolve().then(() => console.log(1));\nsetTimeout(() => console.log(2), 0);  // 1 then 2\n\nreal example:\nWaiting for a promise result before polling a timeout interval only holds for the microtask drain, not the entire task."},{id:12,question:"What is callback-based toPromise conversion and how is it done?",answer:"Wrapping a callback-style function inside a Promise executor converts it to a promise API where resolve and reject are called by the callback.\n\ncode:\nfunction wait(ms) {\n  return new Promise((resolve) => setTimeout(resolve, ms));\n}\nawait wait(1000);\n\nreal example:\nCustom poll helpers in Playwright use this pattern to await arbitrary conditions after a delay."},{id:13,question:"What does awaiting inside a loop do differently from Promise.all?",answer:"Awaited sequentially, each iteration waits for the previous promise, running one by one. Promise.all runs all promises concurrently and waits for all to finish.\n\ncode:\nfor (const url of urls) await fetch(url);      // sequential\nawait Promise.all(urls.map(u => fetch(u)));    // parallel\n\nreal example:\nCreating one-by-one test records stays sequential to respect API rate limits, while read-only checks parallelize."},{id:14,question:"How do you convert an array of promises into their values cleanly?",answer:"Map the workload to promises, then await Promise.all or Promise.allSettled; the results array lines up with the input order.\n\ncode:\nconst totals = await Promise.all(\n  orders.map(o => getTotal(o.id))\n);\n\nreal example:\nFetching product details for a list of ids returns values in the same order, making per-index assertions simple."},{id:15,question:"What is the best practice for handling unhandled promise rejections?",answer:"Always attach catch or await the promise so rejections are observed. Unhandled rejections crash or warn loudly in Node and CI test runners.\n\ncode:\nconst p = risky();\np.catch(err => console.error('handled', err));\n// or: await p;\n\nreal example:\nPlaywright reports unhandled errors as test failures, so route request failures must be awaited or caught to keep logs clean."},{id:16,question:"Why do you need await for waits in Playwright rather than fixed sleep?",answer:"Playwright auto-waits for the actionability of elements with built-in retries, so awaiting locator methods handles slow renders without arbitrary sleeps.\n\ncode:\nawait page.getByRole('button', { name: 'Submit' }).click();\n\nreal example:\nReplacing page.waitForTimeout(3000) with expect(locator).toBeVisible() removes flaky fixed sleeps and speeds the whole suite."}]}},39714,(e,n,t)=>{n.exports={description:"Classes, inheritance and prototypal inheritance.",questions:[{id:1,question:"How do you define a class and instantiate it?",answer:"A class uses the class keyword with a constructor that runs on new. Methods defined in the body are shared across all instances.\n\ncode:\nclass User {\n  constructor(name) {\n    this.name = name;\n  }\n  greet() { return 'Hi ' + this.name; }\n}\nconst u = new User('Ana');\nconsole.log(u.greet());  // Hi Ana\n\nreal example:\nPage Object Models model each page as a class instantiated per test with the page handle."},{id:2,question:"What does the constructor do and can it be omitted?",answer:"The constructor initializes instance fields and runs automatically when new is called. If omitted, an empty constructor is added by default.\n\ncode:\nclass Greeter {}\nconsole.log(new Greeter());  // works, no error\n\nreal example:\nStateless helper classes with no constructor still instantiate cleanly and share their methods."},{id:3,question:"What is the this keyword inside class methods?",answer:"this refers to the instance the method is called on, unless the method is detached and called bare, which loses the binding. Arrow class fields capture this at creation.\n\ncode:\nclass Counter {\n  n = 0;\n  inc() { this.n++; }\n}\nconst c = new Counter();\nc.inc();\nconsole.log(c.n);  // 1\n\nreal example:\nPassing a page object method into an event handler requires the arrow or bind, because a bare reference loses this."},{id:4,question:"What is inheritance and how do you extend a class?",answer:"Inheritance lets a subclass reuse and specialize a base class using the extends keyword, and super calls the base constructor or methods.\n\ncode:\nclass BasePage {\n  constructor(page) { this.page = page; }\n  goto(path) { return this.page.goto(path); }\n}\nclass LoginPage extends BasePage {\n  constructor(page) { super(page); }\n  async login(u, p) { await this.page.fill('#user', u); }\n}\n\nreal example:\nA shared BasePage with navigation and common helpers reduces duplication across page object classes."},{id:5,question:"What does the super keyword do in a subclass?",answer:"super calls the parent constructor or a parent method. Without super(), a derived class cannot initialize and throws when instantiated.\n\ncode:\nclass A { constructor() { console.log('A'); } }\nclass B extends A { constructor() {\n  super();\n  console.log('B');\n} }\nnew B();  // A then B\n\nreal example:\nSubclassed page objects call super(page) first so the base locators exist before the subclass adds its own."},{id:6,question:"What are static methods and properties?",answer:"Static members belong to the class itself rather than instances and are called through the class name, often used for factories and constants.\n\ncode:\nclass Config {\n  static DEFAULT_TIMEOUT = 5000;\n  static create() { return new Config(); }\n}\nconsole.log(Config.DEFAULT_TIMEOUT);  // 5000\n\nreal example:\nStatic factory methods like User.fromApi(json) parse API responses into clean test objects."},{id:7,question:"What are getters and setters in a class?",answer:"Getters and setters expose a computed accessor, so reading and writing a property runs methods instead of touching a field directly.\n\ncode:\nclass Cart {\n  _items = [];\n  get count() { return this._items.length; }\n  add(item) { this._items.push(item); }\n}\nconst c = new Cart();\nc.add('x');\nconsole.log(c.count);  // 1\n\nreal example:\nA summary getter on a page object returns the total so assertions read naturally as page.summary."},{id:8,question:"How does instanceof work?",answer:"instanceof checks whether an object's prototype chain includes a given constructor, which verifies a value was created by a class or its ancestors.\n\ncode:\nclass User {}\nconsole.log(new User() instanceof User);  // true\nconsole.log([] instanceof Object);        // true\n\nreal example:\nAssertions like expect(body).toBeInstanceOf(Array) guard that an API returned the expected collection shape."},{id:9,question:"What is prototypal inheritance?",answer:"Prototypal inheritance means objects inherit from other objects through a hidden [[Prototype]] chain, and classes are syntax sugar over this mechanism.\n\ncode:\nconst base = { greet() { return 'hi'; } };\nconst child = Object.create(base);\nconsole.log(child.greet());  // hi\n\nreal example:\nUnderstanding that locators and browsers resolve shared methods up the prototype chain explains why them.locator works everywhere."},{id:10,question:"How do you access an object's prototype and create one?",answer:"Object.getPrototypeOf reads the prototype, and Object.create establishes a custom prototype for a new object.\n\ncode:\nconst parent = { x: 1 };\nconst child = Object.create(parent);\nconsole.log(Object.getPrototypeOf(child) === parent);  // true\n\nreal example:\nFramework internals use Object.create for lightweight suffix objects, but test code normally sticks to classes."},{id:11,question:"What is the difference between a class method and a class field?",answer:"A method lives on the prototype and is shared, while a class field like count = 0 is created per instance. Fields can also be arrow functions bound to the instance.\n\ncode:\nclass C {\n  method() {}\n  field = 1;\n}\nconst a = new C();\nconst b = new C();\nconsole.log(a.field);  // 1\n\nreal example:\nPer-test instance state belongs in fields so parallel tests never share mutable counters between page objects."},{id:12,question:"How do you make a property truly private in a class?",answer:"Use the hash prefix syntax #field, which is enforced by the language and inaccessible outside the class, unlike underscore conventions.\n\ncode:\nclass Wallet {\n  #balance = 0;\n  deposit(n) { this.#balance += n; }\n}\n// wallet.#balance  // SyntaxError outside the class\n\nreal example:\nPrivate state in page objects prevents tests from tampering with internal cache fields accidentally."},{id:13,question:"What is method overriding in a subclass?",answer:"Overriding means redefining a parent method in the subclass, and you can call the original with super.methodName to extend behavior.\n\ncode:\nclass B extends A {\n  greet() {\n    return super.greet() + '!extra';\n  }\n}\n\nreal example:\nA checkout page overrides the base waitUntilLoaded to also wait for the payment iframe, then calls super for the shared part."},{id:14,question:"How are classes different from constructor functions?",answer:"Classes are a cleaner syntax with strict mode, no hoisting, and you must call them with new. Constructor functions are older and more permissive.\n\ncode:\nfunction OldUser(name) { this.name = name; }\nclass NewUser {}\n// NewUser();  // TypeError: Class constructor cannot be invoked without 'new'\n\nreal example:\nModern test frameworks use classes for page objects, while legacy suites may still show constructor-function helpers."},{id:15,question:"How would you model a Page Object with a class in Playwright?",answer:"Pass the page into the constructor, store it, and expose high-level methods that wrap locator actions so individual tests stay short.\n\ncode:\nclass LoginPage {\n  constructor(page) { this.page = page; }\n  async login(username, password) {\n    await this.page.getByLabel('Username').fill(username);\n    await this.page.getByRole('button', { name: 'Login' }).click();\n  }\n}\n\nreal example:\nEach Playwright test creates the page object, calls login, and asserts on the result without touching raw selectors."}]}},95102,(e,n,t)=>{n.exports={description:"DOM selection, manipulation, events, forms and window.",questions:[{id:1,question:"How do you select a single element in the DOM?",answer:"Use querySelector with a CSS selector for the first match, or getElementById when the element has an id.\n\ncode:\nconst button = document.querySelector('#submit');\nconst title = document.getElementById('page-title');\n\nreal example:\nPlaywright locators mirror this with page.locator('#submit'), selecting the same elements the page DOM exposes."},{id:2,question:"How do you select multiple elements in the DOM?",answer:"querySelectorAll returns a static NodeList of all matches, which you can convert to an array with Array.from or spread.\n\ncode:\nconst rows = document.querySelectorAll('.table-row');\nconst list = [...rows];\nconsole.log(list.length);\n\nreal example:\nCounting rows after a table re-renders uses querySelectorAll length, the same dataset Playwright count() asserts."},{id:3,question:"What is the difference between textContent, innerText, and innerHTML?",answer:"textContent returns all text including hidden nodes and preserves whitespace. innerText reflects only rendered visible text. innerHTML returns the raw markup including tags.\n\ncode:\nconst el = document.querySelector('#box');\nconsole.log(el.textContent);  // plain text\nconsole.log(el.innerHTML);    // includes HTML tags\n\nreal example:\nScraped assertion text should use textContent and trim rather than innerHTML, which returns markup that breaks string comparisons."},{id:4,question:"How do you create an element and add it to the page?",answer:"Create with createElement, fill its properties, then attach with appendChild or insertBefore.\n\ncode:\nconst li = document.createElement('li');\nli.textContent = 'New item';\ndocument.querySelector('#list').appendChild(li);\n\nreal example:\nInjected overlay helpers built for test-only UI reuse this exact create and append pattern."},{id:5,question:"How do you listen for events on an element?",answer:"Use addEventListener with the event type and a callback, allowing multiple listeners on the same element.\n\ncode:\nconst btn = document.querySelector('#pay');\nbtn.addEventListener('click', () => console.log('clicked'));\n\nreal example:\nPlaywright exposes page.on for page events, which is a similar listener pattern for requests and dialogs."},{id:6,question:"What is the event object and what fields are commonly used?",answer:"The event object carries details about the event, such as target, currentTarget, and properties like key or which button was pressed.\n\ncode:\nbtn.addEventListener('click', (event) => {\n  console.log(event.target.id);\n});\n\nreal example:\nForm submit handlers read event.target to reach the input values without extra querying."},{id:7,question:"What is event delegation and why is it useful?",answer:"Event delegation attaches one listener to a parent and catches events from children via bubbling, which works for dynamically added elements and needs fewer listeners.\n\ncode:\ndocument.querySelector('#list').addEventListener('click', (e) => {\n  if (e.target.closest('li')) console.log('row clicked');\n});\n\nreal example:\nTesting row clicks in tables that re-render pagination is stable when a single delegated listener handles all rows."},{id:8,question:"What is event bubbling and how do you stop it?",answer:"Bubbling propagates an event from the target up through its ancestors. Stopping it prevents parent handlers from running using stopPropagation.\n\ncode:\nchild.addEventListener('click', (e) => e.stopPropagation());\n\nreal example:\nA modal close button that should not trigger the row click underneath needs stopPropagation on its handler."},{id:9,question:"How do you read a form input value in JavaScript?",answer:"Access the input element and read its value property, which gives the current user-entered text for text, textarea, and select fields.\n\ncode:\nconst email = document.querySelector('#email').value;\nconsole.log(email);\n\nreal example:\nPlaywright fill then assertions read the same value property when verifying what the user typed."},{id:10,question:"How do you set the value of an input programmatically?",answer:"Assign the input's value property, and for controlled frameworks also dispatch an input event so the app sees the change.\n\ncode:\nconst input = document.querySelector('#name');\ninput.value = 'Ana';\ninput.dispatchEvent(new Event('input', { bubbles: true }));\n\nreal example:\nSetting a value directly bypasses user event paths, which is why React apps need the dispatched event for state to update."},{id:11,question:"What does window.location give you and how do you read the URL parts?",answer:"window.location exposes href, pathname, host, search, and hash for the current page, enabling URL-based assertions.\n\ncode:\nconsole.log(window.location.pathname);\nconsole.log(window.location.search);\n\nreal example:\nAsserting a redirect landed on /checkout?step=1 reads location.pathname and search after an expected navigation."},{id:12,question:"How do you navigate or reload a page with the window API?",answer:"Assign to window.location.href, call window.location.reload(), or use location.assign for a push of a new URL.\n\ncode:\nwindow.location.href = '/orders';\nwindow.location.reload();\n\nreal example:\nA hard refresh helper before a stability check reloads the page to reset transient UI state."},{id:13,question:"What is the difference between a cookie and localStorage data?",answer:"localStorage stores larger string data per origin that persists and is sent to no server, while cookies are small name-value pairs automatically sent with requests.\n\ncode:\nlocalStorage.setItem('token', 'abc');\nconst t = localStorage.getItem('token');\ndocument.cookie = 'session=xyz; path=/';  // web server cookies\n\nreal example:\nUI auth filters grant access client-side via localStorage, but the same token is not available to API requests unless sent as a header."},{id:14,question:"How do you schedule code to run after the page finishes loading?",answer:"Listen for the DOMContentLoaded event on document, or window.load when all resources including images finish loading.\n\ncode:\ndocument.addEventListener('DOMContentLoaded', () => {\n  console.log('tree ready');\n});\n\nreal example:\nAnalytics and feature flags initialized on DOMContentLoaded explain why automated clicks sometimes race early-start listeners."},{id:15,question:"What does stopPropagation vs preventDefault do differently?",answer:"preventDefault cancels the default browser action like a form submit or link navigation. stopPropagation stops the event from bubbling to ancestors.\n\ncode:\nform.addEventListener('submit', (e) => {\n  e.preventDefault();  // stop the page reload\n  doValidation();\n});\n\nreal example:\nSingle-page apps intercept form submits this way; accidental native submit causes page reloads that break Playwright waits."},{id:16,question:"How do you detect when a CDN script finishes executing or fails?",answer:"Attach load and error event listeners during script injection, then observe window state changes after the resource loads.\n\ncode:\nasync function loadScript(src) {\n  return new Promise((resolve, reject) => {\n    const s = document.createElement('script');\n    s.src = src;\n    s.onload = resolve;\n    s.onerror = () => reject(new Error('cdn failed'));\n    document.head.appendChild(s);\n  });\n}\n\nreal example:\nWaiting for an analytics SDK script before asserting its API avoids null-pointer flaky failures in dependency checks."}]}},21874,(e,n,t)=>{n.exports={description:"ES modules, dynamic imports, npm and bundlers.",questions:[{id:1,question:"What is the difference between default and named exports?",answer:"A module can have one default export imported with any name, plus many named exports imported with their exact names in braces.\n\ncode:\nexport default class User {}\nexport const VERSION = '1.0';\n// import User, { VERSION } from './user.js';\n\nreal example:\nTest configs frequently default-export the config object and name-export helpers and constants."},{id:2,question:"How do you import a default export and a named export together?",answer:"Combine them in one import statement: the default name first, then named exports inside braces.\n\ncode:\nimport LoginPage, { buildUser } from './login.js';\n\nreal example:\nPage object files default-export the class while exporting test data builders as named exports."},{id:3,question:"What is the difference between import and require?",answer:"import is the ES module syntax with static analysis and top-level await, while require is CommonJS, synchronous and resolved at runtime.\n\ncode:\nimport fs from 'node:fs';           // ESM\n// const fs = require('node:fs');   // CommonJS\n\nreal example:\nPlaywright config files support both, but ESM-only packages force import while legacy packages may need require."},{id:4,question:"What is a package.json and what is its role?",answer:'package.json is the manifest for a Node project, defining name, version, scripts, and dependencies so npm and frameworks know how to run the project.\n\ncode:\n{\n  "name": "web-tests",\n  "scripts": { "test": "playwright test" },\n  "dependencies": { "@playwright/test": "^1.40.0" }\n}\n\nreal example:\nCI pipelines run npm ci then npm test, which reads scripts and installed versions straight from package.json.'},{id:5,question:"What is the difference between dependencies and devDependencies?",answer:"dependencies are needed to run the app in production, while devDependencies are tools for development such as test runners, linters, and bundlers.\n\ncode:\nnpm install --save-dev playwright\nnpm install axios\n\nreal example:\nPlaywright, Cypress, and Jest belong in devDependencies because they never ship in the production runtime bundle."},{id:6,question:"What is node_modules and why should it not be committed?",answer:"node_modules holds installed packages at every dependency and is regenerated from package-lock.json, so it is gitignored to keep repos small and reproducible.\n\ncode:\nnode_modules/\n\nreal example:\nTeams run npm ci in CI which wipes and reinstalls from the lockfile, guaranteeing byte-for-byte identical dependency trees."},{id:7,question:"What is the difference between npm install and npm ci?",answer:"npm install reads package.json and may update the lockfile, while npm ci installs exactly the versions pinned in package-lock.json and fails if they do not match.\n\ncode:\nnpm ci\n\nreal example:\nCI uses npm ci because it is faster and gives exact versions, eliminating works-on-my-machine flakiness."},{id:8,question:"What is npx and how is it different from npm?",answer:"npx runs a package binary without installing it globally, downloading and caching it on demand or using the local project version.\n\ncode:\nnpx playwright install\nnpx cypress open\n\nreal example:\nHelping a teammate run the exact local test runner without global installs is the primary npx job."},{id:9,question:"What are npm scripts and how are they used?",answer:'npm scripts are commands defined in package.json under scripts, run through npm run name to share and standardize workflow commands.\n\ncode:\n"scripts": {\n  "test": "playwright test",\n  "test:headed": "playwright test --headed"\n}\n\nreal example:\nUsers type npm run test:headed in CI manifests instead of remembering long runner flags.'},{id:10,question:"What is a bundler and why do browsers need one?",answer:"A bundler like webpack, Vite, or esbuild combines many modules into fewer files browsers can load fast, handling imports, plugins, and assets.\n\ncode:\nnpx vite build\n\nreal example:\nTesting the built bundle means running the production build because dev servers serve modules differently than the bundled output."},{id:11,question:"What is tree shaking?",answer:"Tree shaking removes unused exports from the final bundle by static analysis, keeping only code that is actually imported.\n\ncode:\nimport { onlyUsed } from './utils.js';\n\nreal example:\nBundle-size checks and load budgets depend on tree shaking keeping third-party helpers that are never called out of the shipped file."},{id:12,question:"What is a dynamic import and when would you use it?",answer:"Dynamic import loads a module on demand with import(expression), returning a promise, useful for heavy features that are not needed at startup.\n\ncode:\nconst { chart } = await import('./heavy-chart.js');\nchart.render();\n\nreal example:\nLazy-loaded modules only exist on the page after the import resolves, which changes what an automation scan sees at load time."},{id:13,question:"Why does import order matter for side-effect modules?",answer:"Side-effect imports run their top-level code on load, so ordering determines when global patches, styles, or polyfills apply.\n\ncode:\nimport './styles.css';\nimport './polyfills.js';\n\nreal example:\nInjecting a mock module before the app entry point in test setups mirrors this ordering behavior to override globals early."},{id:14,question:"What is the difference between ESM and CommonJS module systems?",answer:"ESM is the modern standard with static imports and async loading, while CommonJS is Node's older synchronous system with require and module.exports.\n\ncode:\n// ESM\nimport x from './x.js';\nexport default x;\n// CommonJS\nconst x = require('./x');\nmodule.exports = x;\n\nreal example:\nSome testing tools are CommonJS-only, so team configs sometimes choose .cjs extensions to keep one consistent system."},{id:15,question:"Why does the package.json type field matter for modules?",answer:'The type field marks a package as module or commonjs, which decides whether .js files interpret import/export or require syntax.\n\ncode:\n"type": "module"\n\nreal example:\nSetting type module lets playwright.config.js use import directly, while omitting it forces CommonJS require in the same file.'}]}},78830,(e,n,t)=>{n.exports={description:"Regular expressions for test assertions.",questions:[{id:1,question:"How do you create a regular expression in JavaScript?",answer:"Use a regex literal between slashes without quotes, or the RegExp constructor when the pattern is built dynamically.\n\ncode:\nconst id = /^[A-Z]{3}-\\d{4}$/;\nconst dynamic = new RegExp('order-' + number);\n\nreal example:\nPlaywright selectors accept regex like page.getByText(/In stock/i) for flexible text matching."},{id:2,question:"What does the test method do on a regex?",answer:"The test method returns true when the pattern matches anywhere in the string and false otherwise.\n\ncode:\nconsole.log(/\\d+/.test('price 42'));  // true\nconsole.log(/\\d+/.test('abc'));       // false\n\nreal example:\nAsserting a response body matches an expected shape uses regex.test on values before deeper extraction."},{id:3,question:"What is the difference between test, exec, and match?",answer:"test returns a boolean, exec returns detailed match arrays with capture groups, and match is the string method that does the same for the string.\n\ncode:\nconst m = /(\\d+)-(\\d+)/.exec('order-12-45');\nconsole.log(m[1]);   // 12\nconsole.log('12-45'.match(/(\\d+)/)[1]);  // 12\n\nreal example:\nExtracting the id from a URL route with exec gives the integer group used in a follow-up API request."},{id:4,question:"What do the g, i, and m flags do?",answer:"g makes the search global so match returns all occurrences, i makes matching case-insensitive, and m makes ^ and $ match per line instead of the whole string.\n\ncode:\nconsole.log('a b a'.match(/a/g).length);  // 2\nconsole.log(/login/i.test('LOGIN'));      // true\n\nreal example:\nCase-insensitive text equality in Cypress like expect(text).to.match(/successfully/i) ignores case and punctuation variance."},{id:5,question:"What do anchors ^ and $ mean in a regex?",answer:"^ anchors the match to the start of the string and $ anchors it to the end, so /^abc$/ matches exactly abc and nothing longer.\n\ncode:\nconsole.log(/^done$/.test('done'));    // true\nconsole.log(/^done$/.test('done!'));   // false\n\nreal example:\nEnforcing exact status text like successful login uses anchors so partial matches never pass an assertion."},{id:6,question:"What are character classes such as \\d, \\w, and \\s?",answer:"\\d matches any digit, \\w any word character, and \\s any whitespace. Their uppercase forms match the negation.\n\ncode:\nconst re = /^\\w{3}\\d{2}$/;\nconsole.log(re.test('abc12'));  // true\n\nreal example:\nValidating phone and zip formats before posting to an API uses character classes in the pattern."},{id:7,question:"How do quantifiers like *, +, and ? work?",answer:"* matches zero or more, + matches one or more, and ? matches zero or one of the preceding token, controlling repetition by default greedily.\n\ncode:\nconsole.log(/a+/.test(''));        // false\nconsole.log(/a*/.test(''));        // true\nconsole.log(/colou?r/.test('color')); // true\n\nreal example:\nTax and currency parsing tolerances like optional spaces or decimal parts rely on ? quantifiers."},{id:8,question:"What is a capture group and how do you use it?",answer:"A capture group is a parenthesized part of the pattern that is stored separately, accessible by index from exec or match results.\n\ncode:\nconst m = 'order-5533'.match(/order-(\\d+)/);\nconsole.log(m[1]);  // 5533\n\nreal example:\nExtracting a numeric order id from confirmation text then using it in a database lookup is a classic capture-group task."},{id:9,question:"How do you replace text using a regex?",answer:"Pass a regex to replace, optionally with the g flag for all occurrences, and reference capture groups with $1 and friends.\n\ncode:\nconsole.log('2026-01-05'.replace(/(\\d{4})-(\\d{2})-(\\d{2})/, '$3/$2/$1'));\n// 05/01/2026\n\nreal example:\nNormalizing date formats scraped from varying locales before comparison is done with a regex replace."},{id:10,question:"What is the difference between the literal and the RegExp constructor?",answer:"The literal /pattern/ is static and compiled once, while new RegExp('pattern') builds from a string, which is necessary for patterns generated at runtime.\n\ncode:\nconst prefix = 'product-';\nconst re = new RegExp('^' + prefix + '\\\\d+$');\nconsole.log(re.test('product-42'));  // true\nconsole.log(re.test('product-abc')); // false\n\nreal example:\nBuilding a validator for dynamic prefixes keeps the pattern parametrized while escaping user-provided search terms prevents regex injection."},{id:11,question:"How do you use a regex in a Playwright assertion?",answer:"Playwright matchers accept regex where strings are expected, so text, attribute, and URL checks support patterns.\n\ncode:\nawait expect(page).toHaveURL(/\\/checkout\\?step=\\d+/);\nawait expect(page.getByText(/order confirmed/i)).toBeVisible();\n\nreal example:\nAsserting a redirect URL pattern instead of an exact URL keeps assertions stable across query param order."},{id:12,question:"What does a lookahead like (?=...) do?",answer:"A lookahead asserts that the pattern inside exists ahead without including it in the match, enabling complex password and format validations.\n\ncode:\nconst strong = /^(?=.*[A-Z])(?=.*\\d).+$/;\nconsole.log(strong.test('Ab1'));  // true\n\nreal example:\nSignup form validation checks (uppercase plus digit) are commonly encoded as lookaheads asserted by the test."},{id:13,question:"What does the . (dot) match and how do you match a literal dot?",answer:"The dot matches any single character except a newline by default. To match an actual dot or any metacharacter literally, escape it with a backslash.\n\ncode:\nconsole.log(/a.b/.test('acb'));  // true\nconsole.log(/a\\.b/.test('a.b')); // true\n\nreal example:\nParsing version strings like 1.2.3 requires escaped dots, otherwise any character wrongly satisfies the pattern."},{id:14,question:"How do you create a regex to match an email address?",answer:"A practical pattern uses character classes and escaped symbols, though perfect RFC email validation in one line is unrealistic.\n\ncode:\nconst email = /^[\\w.+-]+@[\\w-]+\\.[\\w.]+$/;\nconsole.log(email.test('user+test@example.com'));  // true\n\nreal example:\nAsserting server responses contain valid email addresses uses the same pattern to reject obvious malformed values."},{id:15,question:"Why is the global flag required for matchAll or replace all?",answer:"matchAll and global replace operate across the entire string, so an inner regex without g matches only the first occurrence.\n\ncode:\nconst all = 'a1b2'.matchAll(/\\d/g);\nconsole.log([...all].map(m => m[0]));  // ['1', '2']\n\nreal example:\nCounting occurrences of a tag in raw HTML uses a global regex; relying on non-global patterns under-counts matches in tests."}]}},53654,(e,n,t)=>{n.exports={description:"Cross-topic questions automation testers are asked.",questions:[{id:1,question:"What is the difference between == and === and which should test assertions use?",answer:"The loose equality == coerces types before comparing, while strict === requires both type and value to match. Automated assertions should use strict equality so a string and a number never match accidentally.\n\ncode:\nconsole.log('42' == 42);   // true\nconsole.log('42' === 42);  // false\n\nreal example:\nPlaywright text matchers compare strings, so converting page text to numbers before toBe comparisons follows the strict-equality rule."},{id:2,question:"What is a flaky test and how do you reduce it in JavaScript automation?",answer:"A flaky test passes and fails intermittently, usually from timing, ordering, or environment issues. Reduce it with auto-waiting, deterministic selectors, isolated test data, and no fixed sleeps.\n\ncode:\nawait expect(page.getByRole('button', { name: 'Save' })).toBeVisible();\nawait page.getByRole('button', { name: 'Save' }).click();\n\nreal example:\nReplacing page.waitForTimeout(2000) with Playwright actionability waits removes the most common fixed-delay flakiness in UI suites."},{id:3,question:"Why should you prefer data-testid selectors over CSS classes in tests?",answer:"Data attributes like data-testid are stable contracts between tests and developers, while class names change for styling and break selectors silently.\n\ncode:\npage.getByTestId('checkout-button').click();\n// vs a brittle ,class list like  .btn-primary.rounded\n\nreal example:\nTeams agree that test hooks use data-testid so refactors of CSS never degrade the E2E suite."},{id:4,question:"What is the difference between wait and auto-wait in Playwright?",answer:"Auto-wait means actions retry until the element is actionable within the timeout, checking visibility, stability, and enabled state. Manual waits only sleep or poll once without retry guarantees.\n\ncode:\nawait page.getByRole('button').click();  // auto-waits\n\nreal example:\nAuto-wait turns a slow-loading modal into a passing test, while page.waitForTimeout can let clicks land before a re-render simply breaks the canvas."},{id:5,question:"How do you handle a popup dialog that appears during a test?",answer:"Register listeners before the trigger so the dialog event is captured, then dismiss or accept it, otherwise the browser throws unhandled-dialog errors.\n\ncode:\npage.on('dialog', dialog => dialog.accept());\nawait page.getByRole('button', { name: 'Delete' }).click();\n\nreal example:\nConfirming a native alert before clicking the destructive button prevents the mid-click dialog from hanging the action."},{id:6,question:"What is the event loop and how does it relate to async test code?",answer:"The event loop coordinates the single-threaded call stack, microtask queue, and macrotask queue so promises and timers run in order. Test awaits compose on it to keep steps ordered.\n\ncode:\nsetTimeout(() => console.log('later'), 0);\nconsole.log('first');  // first, later\n\nreal example:\nPromise callbacks run before timeout callbacks, which is why an await for a promise result reliably precedes a setTimeout-based poll."},{id:7,question:"What is the difference between Promise.all and Promise.allSettled in test setup?",answer:"Promise.all rejects at the first failure and returns values on full success, while allSettled always resolves with per-promise status so you can inspect every outcome.\n\ncode:\nconst results = await Promise.allSettled(\n  endpoints.map(url => fetchStatus(url))\n);\n\nreal example:\nSetup that seeds accounts wants to fail fast with all, while a health-check report wants every endpoint's status via allSettled."},{id:8,question:"Why is the page object model a preferred pattern in UI automation?",answer:"The page object model centralizes selectors and actions for a page in one class, so tests read like business steps and selector changes update in one place.\n\ncode:\nclass LoginPage {\n  constructor(page) { this.page = page; }\n  async login(user, pass) {\n    await this.page.getByLabel('Username').fill(user);\n    await this.page.getByRole('button', { name: 'Sign in' }).click();\n  }\n}\n\nreal example:\nA renaming of the sign-in button updates LoginPage once instead of across every spec that logs in."},{id:9,question:"How do you test an API response before testing the UI that uses it?",answer:"Send the request with the request fixture or fetch, assert the status and body shape, then drive the UI and compare the rendered result against that contract.\n\ncode:\nconst res = await request.get('/api/config');\nexpect(res.status()).toBe(200);\nexpect(Number(res.body.featureFlags.length)).toBeGreaterThan(0);\n\nreal example:\nIf the API returns total count in the body, the UI total must equal that number, so a single source of truth reduces conflicting expectations."},{id:10,question:"What is JSON.parse wrap in a try/catch and why is it important?",answer:"JSON.parse throws a SyntaxError for malformed input, so wrapping it lets you report a clean message instead of a raw parser crash that hides the real contract violation.\n\ncode:\ntry {\n  const data = JSON.parse(responseBody);\n} catch {\n  throw new Error('Server returned invalid JSON');\n}\n\nreal example:\nA server-side error page returned as HTML triggers JSON.parse to throw, and the try/catch turns it into an explicit assertion failure."},{id:11,question:"How do you share setup across many JavaScript tests?",answer:"Test frameworks provide hooks: beforeEach and beforeAll in Jest and Vitest, or Playwright fixtures that inject fresh state per test.\n\ncode:\nbeforeEach(() => {\n  localStorage.clear();\n});\n\nreal example:\nPlaywright uses fixtures like const test = base.extend({ user: async ({}, use) => {...} }) so every test gets isolated data."},{id:12,question:"What is the difference between a unit test and an end-to-end test?",answer:"A unit test isolates one function or module with mocks and runs in milliseconds, while an E2E test runs the full browser stack and verifies real user flows end to end.\n\ncode:\n// unit: expect(calculateTax(100)).toBe(10);\n// e2e: await page.goto('/checkout'); await expect(page).toHaveText('$110');\n\nreal example:\nTeams cover pricing with unit tests on the calculator and a thin E2E layer that confirms the string actually renders on the checkout page."},{id:13,question:"What is meant by a retry policy and how does it apply to automation?",answer:"A retry policy reruns a failed test a bounded number of times to filter transient infrastructure flakes, configured in the test runner rather than inside the test logic.\n\ncode:\ndefineConfig({\n  retries: process.env.CI ? 2 : 0,\n});\n\nreal example:\nCI flakiness from slow first-load requests drops when Playwright retries failed specs, while local development stays fast with zero retries."},{id:14,question:"What does console.error do and where should error logging live in tests?",answer:"console.error prints a stack to stderr, and uncaught console errors in a browser session are often asserted as page errors in E2E frameworks.\n\ncode:\npage.on('pageerror', (err) => {\n  console.error('page threw:', err.message);\n});\n\nreal example:\nListening to pageerror catches silent script failures that break flows, even when the visible assertion alone passes."},{id:15,question:"What is the significance of a lockfile such as package-lock.json in CI?",answer:"A lockfile pins exact indirect dependency versions, so npm ci installs the identical tree everywhere and CI results stay reproducible between machines.\n\ncode:\nnpm ci\nnpx playwright test\n\nreal example:\nCI fails rarely when a lockfile exists because version drift between developer laptops and the pipeline disappears."},{id:16,question:"What happens when you evaluate code inside page.evaluate and how do you return values?",answer:"page.evaluate runs a function in the browser context and serializes its return value back to Node, enabling checks on browser-only state like window.cookies or local geometry.\n\ncode:\nconst width = await page.evaluate(() => {\n  return window.innerWidth;\n});\nconsole.log(width);\n\nreal example:\nAsserting a responsive breakpoint applies measures layout with evaluate, then compares the returned width against the expected design value."}]}},41506,e=>{"use strict";var n=e.i(13974),t=e.i(35999),a=e.i(54916),s=e.i(51010),o=e.i(95907),r=e.i(12877),i=e.i(60349),l=e.i(43492),c=e.i(11603),d=e.i(3866),u=e.i(39714),h=e.i(95102),p=e.i(21874),m=e.i(78830),g=e.i(53654);let f={js_basics:n.default,js_operators:t.default,js_control_flow:a.default,js_strings:s.default,js_functions:o.default,js_arrays:r.default,js_objects:i.default,js_map_set:l.default,js_json_fetch:c.default,js_async:d.default,js_classes:u.default,js_dom:h.default,js_modules:p.default,js_regex:m.default,js_interview:g.default};e.s(["getSection",0,function(e){return f[e]}])}]);